/* Task-specific suggested action and evidence. Does not approve or execute a task. */
(function(root){
const g=root.FNClinicalGuidelines||(typeof require==='function'?require('./clinical-guidelines.js'):null),abx=root.FNAntibioticOrders||(typeof require==='function'?require('./antibiotic-orders-core.js'):null),action=root.FNAction||(typeof require==='function'?require('./action-core.js'):null);
const catalog={
 review:{title:'Review current clinical status',reason:'Current clinical findings and instability take priority over the score.',sources:['agiho','fn']},
 allergy:{title:'Verify allergies and previous antimicrobial doses',reason:'Reaction history and recent doses inform a safe regimen and avoid duplication.',sources:['fn']},
 labs:{title:'Request or review the required laboratory assessment',reason:'Blood counts and organ function support the clinical and dosing review.',sources:['agiho']},
 cultures:{title:'Collect or verify blood cultures',reason:'Obtain indicated cultures before antibiotics when feasible, without delaying urgent treatment.',sources:['agiho','outpatient']},
 lactate:{title:'Review perfusion and the need for lactate testing',reason:'Possible deterioration requires prompt clinical assessment and escalation when indicated.',sources:['agiho']},
 source:{title:'Assess the suspected infection source',reason:'Source findings guide targeted investigations and subsequent treatment review.',sources:['agiho']},
 pharmacy:{title:'Review the proposed antibiotic regimen',reason:'Check indication, allergy, renal dosing, interactions and infusion before authorization.',sources:['fn']},
 antibiotic:{title:'Review the suggested antibiotic order set',reason:'Select timely empirical treatment for the current FN pathway, accounting for safety and local policy.',sources:['fn','outpatient']},
 reassess:{title:'Reassess findings and treatment response',reason:'Serial assessment and available microbiology guide the next clinical decision.',sources:['agiho']},
 disposition:{title:'Review the appropriate care setting',reason:'Outpatient disposition needs clinical and practical eligibility beyond a reassuring MASCC score.',sources:['outpatient','agiho']},
 change_review:{title:'Review the changed patient findings',reason:'A new result or clinical change needs a current review and documented decision.',sources:['agiho']}
};
function build(d,t){if(!t||!d.tasks.some(x=>x.id===t.id))throw Error('Select a task from this encounter.');const c=catalog[t.code]||{title:'Review this clinician-defined task',reason:'Use the documented task requirement and record the reason for the chosen action.',sources:[]};let order=null;
 if(t.code==='antibiotic'){const prior=d.tasks.some(x=>x.code==='antibiotic'&&x.status==='completed'),p={...d.input,priorAntibiotic:prior?true:d.input.priorAntibiotic};order=abx.build(p,{...action.calculate(p,{},0),...d.current,meds:prior?[]:d.current.meds},{patientId:d.patientId,protocol:d.protocol,formulary:d.protocol.allowedDrugs,priorDoseRecorded:prior,reports:d.tests.map(x=>x.latest)})}
 const references=new Map(c.sources.map(k=>[k,{id:k,...g.sources[k]}]));if(order)for(const m of order.items)for(const r of m.references)references.set(r.key,{id:r.key,...r});
 const scope={patientId:d.patientId,taskId:t.id,code:t.code,taskTitle:t.title,inputRevision:d.revision,input:d.input,protocol:{name:d.protocol.name,version:d.protocol.version,status:d.protocol.status},reports:d.tests.map(x=>x.latest?[x.id,x.latest.id,x.latest.status,x.latest.ast||{}]:null),holds:order?.holds||[]};
 return {version:'FN-TASK-GUIDANCE-1.0',signature:JSON.stringify(scope),patientId:d.patientId,taskId:t.id,taskCode:t.code,inputRevision:d.revision,title:c.title,suggestedAction:t.title,ruleId:'FN-TASK-'+t.code.toUpperCase(),ruleContext:d.current.risk+' · current assessment revision '+d.revision,reason:c.reason,rationale:[{id:'task:'+t.code,text:c.reason,sources:c.sources}],references:[...references.values()],order,clinicallyApproved:false};
}
function resolve(card,raw={},required=false){if((raw.signature||required)&&raw.signature!==card.signature)throw Error('The task or patient context changed. Reopen Manage action and review the current suggestion.');const valid=(v,list)=>{if(!Array.isArray(v)||v.some(k=>!list.some(x=>x.id===k)))throw Error('Use only the suggestions and references offered for this task.');return [...new Set(v)]};const rationaleIds=valid(raw.rationaleIds||[],card.rationale),evidenceIds=valid(raw.evidenceIds||[],card.references),chosen=card.rationale.filter(x=>rationaleIds.includes(x.id)),refs=card.references.filter(x=>evidenceIds.includes(x.id));const complete=chosen.length>0&&chosen.every(x=>x.sources.length===0||x.sources.some(k=>evidenceIds.includes(k)));if(required&&!complete)throw Error('Choose a supporting reference for the selected task rationale.');return {version:card.version,signature:card.signature,taskId:card.taskId,inputRevision:card.inputRevision,suggestedAction:card.suggestedAction,ruleId:card.ruleId,rationaleIds,evidenceIds,rationale:chosen,references:refs,complete}}
function note(s){return ['Suggested action: '+s.suggestedAction,...s.rationale.map(x=>'Rationale: '+x.text),...s.references.map(x=>'Evidence: '+x.title+' ('+(x.version||'dosing reference')+')')].join('\n')}
const api={build,resolve,note,catalog};root.FNTaskGuidance=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
